    10→export async function dockerRoutes(fastify: FastifyInstance) {
    11→    const cacheMs = Math.max(0, parseInt(process.env.DOCKER_STATUS_CACHE_MS || '1500', 10) || 0);
    12→
    13→    let containersCache: Container[] | null = null;
    14→    let containersCacheAt = 0;
    15→    let containersInFlight: Promise<Container[]> | null = null;
    16→    let composeServicesCache: string[] | null = null;
    17→    let composeServicesCacheAt = 0;
    18→    let composeServicesInFlight: Promise<string[]> | null = null;
    19→
    20→    const isDockerUnavailable = (error: unknown) => {
    21→        const msg = getErrorMessage(error).toLowerCase();
    22→        return msg.includes('docker daemon is not running')
    23→            || msg.includes('docker: command not found')
    24→            || msg.includes('required cli')
    25→            || msg.includes('docker cli is not available')
    26→            || msg.includes('connect to the docker daemon')
    27→            || msg.includes('no such file or directory') && msg.includes('docker');
    28→    };
    29→
    30→    // Detect compose configuration errors (missing env vars, invalid yaml, etc.)
    31→    const isComposeConfigError = (error: unknown) => {
    32→        const msg = getErrorMessage(error).toLowerCase();
    33→        return msg.includes('required variable')
    34→            || msg.includes('is missing a value')
    35→            || msg.includes('error while interpolating')
    36→            || msg.includes('yaml:')
    37→            || msg.includes('invalid compose');
    38→    };
    39→
    40→    const getComposeServices = async (): Promise<string[]> => {
    41→        const now = Date.now();
    42→        if (cacheMs > 0 && composeServicesCache && now - composeServicesCacheAt < cacheMs) {
    43→            return composeServicesCache;
    44→        }
    45→        if (composeServicesInFlight) return composeServicesInFlight;
    46→
    47→        composeServicesInFlight = (async () => {
    48→            try {
    49→                const output = await runCommand('docker', ['compose', '--project-directory', PROJECT_ROOT, 'config', '--services'], {
    50→                    timeoutMs: 10_000,
    51→                    label: 'compose:services',
    52→                });
    53→                const services = output
    54→                    .split('\n')
    55→                    .map((s) => s.trim())
    56→                    .filter(Boolean);
    57→                if (cacheMs > 0) {
    58→                    composeServicesCache = services;
    59→                    composeServicesCacheAt = Date.now();
    60→                }
    61→                return services;
    62→            } catch (err) {
    63→                // If compose config fails (missing .env, etc.), return empty and cache briefly
    64→                if (isComposeConfigError(err)) {
    65→                    if (cacheMs > 0) {
    66→                        composeServicesCache = [];
    67→                        composeServicesCacheAt = Date.now();
    68→                    }
    69→                    return [];
    70→                }
    71→                throw err;
    72→            }
    73→        })();
    74→
    75→        try {
    76→            return await composeServicesInFlight;
    77→        } finally {
    78→            composeServicesInFlight = null;
    79→        }
    80→    };
    81→
    82→    const composeActionArgs = (extra: string[] = []) => ['compose', '--project-directory', PROJECT_ROOT, ...extra];
    83→
    84→    // Get Container Status
    85→    fastify.get('/api/containers', async (request, reply) => {
    86→        try {
    87→            const now = Date.now();
    88→            if (cacheMs > 0 && containersCache && now - containersCacheAt < cacheMs) {
    89→                return containersCache;
    90→            }
    91→
    92→            if (containersInFlight) {
    93→                return await containersInFlight;
    94→            }
    95→
    96→            containersInFlight = (async () => {
    97→                const output = await runCommand(
    98→                    'docker',
    99→                    ['ps', '-a', '--format', '"{{.ID}}|{{.Names}}|{{.Status}}|{{.State}}|{{.Ports}}"'],
   100→                    { timeoutMs: 12_000, label: 'docker ps' }
   101→                );
   102→
   103→                const containers: Container[] = output
   104→                    .split('\n')
   105→                    .map((line) => line.replace(/"/g, '').trim())
   106→                    .filter((line) => Boolean(line))
   107→                    .map((line) => {
   108→                        const [id, name, status, state, ports] = line.split('|');
   109→                        if (!name || !name.trim()) return null;
   110→                        return {
   111→                            id: (id || '').trim(),
   112→                            name: name.trim(),
   113→                            status: (status || '').trim(),
   114→                            state: (state || '').trim(),
   115→                            ports: (ports || '').trim(),
   116→                        };
   117→                    })
   118→                    .filter((c): c is Container => Boolean(c));
   119→
   120→                if (cacheMs > 0) {
   121→                    containersCache = containers;
   122→                    containersCacheAt = Date.now();
   123→                }
   124→
   125→                return containers;
   126→            })();
   127→
   128→            try {
   129→                return await containersInFlight;
   130→            } finally {
   131→                containersInFlight = null;
   132→            }
   133→        } catch (error: unknown) {
   134→            fastify.log.error({ err: error }, 'Error fetching containers');
   135→            if (isDockerUnavailable(error)) {
   136→                return reply.status(503).send({
   137→                    error: 'docker_unavailable',
   138→                    message: getErrorMessage(error),
   139→                    containers: []
   140→                });
   141→            }
   142→            reply.status(500).send({ error: getErrorMessage(error) });
   143→        }
   144→    });
   145→
   146→    // Start/Stop/Restart a Service
   147→    fastify.post<{ Params: { action: string }, Body: { serviceName: string } }>(
   148→        '/api/service/:action',
   149→        async (request, reply) => {
   150→            const { action } = request.params;
   151→            const parseBody = z.object({ serviceName: z.string().min(1) }).safeParse(request.body);
   152→            if (!parseBody.success) {
   153→                return reply.status(400).send({ error: 'Invalid service name' });
   154→            }
   155→            const { serviceName } = parseBody.data;
   156→
   157→            if (!['start', 'stop', 'restart', 'up'].includes(action)) {
   158→                return reply.status(400).send({ error: 'Invalid action' });
   159→            }
   160→
   161→            try {
   162→                const services = await getComposeServices();
   163→                if (!services.includes(serviceName)) {
   164→                    return reply
   165→                        .status(400)
   166→                        .send({ error: `Unknown service "${serviceName}". Known services: ${services.join(', ') || 'none'}` });
   167→                }
   168→
   169→                let cmdArgs: string[] = [];
   170→                if (action === 'up') {
   171→                    cmdArgs = composeActionArgs(['up', '-d', serviceName]);
   172→                } else if (action === 'start') {
   173→                    cmdArgs = composeActionArgs(['start', serviceName]);
   174→                } else if (action === 'stop') {
   175→                    cmdArgs = composeActionArgs(['stop', serviceName]);
   176→                } else if (action === 'restart') {
   177→                    cmdArgs = composeActionArgs(['restart', serviceName]);
   178→                }
   179→
   180→                await runCommand('docker', cmdArgs, { timeoutMs: 20_000, label: `compose:${action}:${serviceName}` });
   181→                return { success: true, message: `Service ${serviceName} ${action}ed successfully` };
   182→            } catch (error: unknown) {
   183→                fastify.log.error({ err: error, action, serviceName }, 'Error performing action on service');
   184→                reply.status(500).send({ error: getErrorMessage(error) });
   185→            }
   186→        },
   187→    );
   188→
   189→    // Run Updates
   190→    fastify.post('/api/system/update', async (request, reply) => {
   191→        try {
   192→            await runCommand('docker', composeActionArgs(['pull']), { timeoutMs: 60_000, label: 'compose:pull' });
   193→            await runCommand('docker', composeActionArgs(['up', '-d', '--remove-orphans']), {
   194→                timeoutMs: 60_000,
   195→                label: 'compose:up',
   196→            });
   197→            await runCommand('docker', ['image', 'prune', '-f'], { timeoutMs: 30_000, label: 'docker:image-prune' });
   198→            return { success: true, message: 'System updated successfully' };
   199→        } catch (error: unknown) {
   200→            reply.status(500).send({ error: getErrorMessage(error) });
   201→        }
   202→    });
   203→
   204→    fastify.post('/api/system/restart', async (_request, reply) => {
   205→        try {
   206→            await runCommand('docker', composeActionArgs(['restart']), { timeoutMs: 30_000, label: 'compose:restart' });
   207→            return { success: true, message: 'System restarted successfully' };
