    10→import { createLogger } from '../utils/logger.js';
    11→
    12→const logger = createLogger('metrics');
    13→
    14→const METRICS_DIR = join(PROJECT_ROOT, 'data', 'metrics');
    15→const METRICS_FILE = join(METRICS_DIR, 'agent_metrics.json');
    16→
    17→// Model pricing (per 1M tokens, as of January 2026) - OpenAI only
    18→const MODEL_PRICING: Record<string, { input: number; output: number }> = {
    19→    'gpt-4o': { input: 2.50, output: 10.00 },
    20→    'gpt-4o-mini': { input: 0.15, output: 0.60 },
    21→    'tts-1': { input: 15.00, output: 0 },
    22→    'tts-1-hd': { input: 30.00, output: 0 },
    23→    'gpt-4o-mini-tts': { input: 15.00, output: 0 }
    24→};
    25→
    26→export interface RequestMetric {
    27→    timestamp: string;
    28→    requestId: string;
    29→    agent: string;
    30→    model: string;
    31→    provider: 'openai';
    32→    promptTokens: number;
    33→    completionTokens: number;
    34→    totalTokens: number;
    35→    latencyMs: number;
    36→    success: boolean;
    37→    error?: string;
    38→    toolsUsed: string[];
    39→    fallbackUsed: boolean;
    40→}
    41→
    42→export interface AggregatedMetrics {
    43→    period: 'hour' | 'day' | 'week' | 'month';
    44→    startTime: string;
    45→    endTime: string;
    46→    totalRequests: number;
    47→    successfulRequests: number;
    48→    failedRequests: number;
    49→    totalTokens: number;
    50→    totalPromptTokens: number;
    51→    totalCompletionTokens: number;
    52→    averageLatencyMs: number;
    53→    p95LatencyMs: number;
    54→    estimatedCostUsd: number;
    55→    requestsByAgent: Record<string, number>;
    56→    requestsByModel: Record<string, number>;
    57→    toolUsage: Record<string, number>;
    58→    fallbackRate: number;
    59→    errorRate: number;
    60→}
    61→
    62→interface MetricsStore {
    63→    version: number;
    64→    lastUpdated: string;
    65→    requests: RequestMetric[];
    66→    aggregated: {
    67→        hourly: AggregatedMetrics[];
    68→        daily: AggregatedMetrics[];
    69→    };
    70→}
    71→
    72→let metricsStore: MetricsStore = {
    73→    version: 1,
    74→    lastUpdated: new Date().toISOString(),
    75→    requests: [],
    76→    aggregated: { hourly: [], daily: [] }
    77→};
    78→
    79→// In-memory buffer for high-frequency writes
    80→const requestBuffer: RequestMetric[] = [];
    81→const BUFFER_FLUSH_INTERVAL = 30000; // 30 seconds
    82→const MAX_BUFFER_SIZE = 100;
    83→const MAX_STORED_REQUESTS = 10000;
    84→
    85→async function ensureDir(): Promise<void> {
    86→    try {
    87→        await mkdir(METRICS_DIR, { recursive: true });
    88→    } catch { /* exists */ }
    89→}
    90→
    91→async function loadMetrics(): Promise<void> {
    92→    try {
    93→        await ensureDir();
    94→        const data = await readFile(METRICS_FILE, 'utf-8');
    95→        metricsStore = JSON.parse(data);
    96→        logger.info({ requestCount: metricsStore.requests.length }, 'Loaded metrics');
    97→    } catch {
    98→        // Start fresh
    99→        metricsStore = {
   100→            version: 1,
   101→            lastUpdated: new Date().toISOString(),
   102→            requests: [],
   103→            aggregated: { hourly: [], daily: [] }
   104→        };
   105→    }
   106→}
   107→
   108→async function saveMetrics(): Promise<void> {
   109→    try {
   110→        await ensureDir();
   111→
   112→        // Add buffered requests
   113→        metricsStore.requests.push(...requestBuffer);
   114→        requestBuffer.length = 0;
   115→
   116→        // Trim old requests
   117→        if (metricsStore.requests.length > MAX_STORED_REQUESTS) {
   118→            metricsStore.requests = metricsStore.requests.slice(-MAX_STORED_REQUESTS);
   119→        }
   120→
   121→        metricsStore.lastUpdated = new Date().toISOString();
   122→        await writeFile(METRICS_FILE, JSON.stringify(metricsStore, null, 2));
   123→    } catch (err) {
   124→        logger.error({ err }, 'Failed to save metrics');
   125→    }
   126→}
   127→
   128→// Periodic flush
   129→setInterval(() => {
   130→    if (requestBuffer.length > 0) {
   131→        saveMetrics();
   132→    }
   133→}, BUFFER_FLUSH_INTERVAL);
   134→
   135→/**
   136→ * Record a request metric
   137→ */
   138→export function recordRequest(metric: Omit<RequestMetric, 'timestamp' | 'requestId'>): void {
   139→    const fullMetric: RequestMetric = {
   140→        ...metric,
   141→        timestamp: new Date().toISOString(),
   142→        requestId: `req_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`
   143→    };
   144→
   145→    requestBuffer.push(fullMetric);
   146→
   147→    // Flush if buffer is full
   148→    if (requestBuffer.length >= MAX_BUFFER_SIZE) {
   149→        saveMetrics();
   150→    }
   151→
   152→    // Log for real-time observability
   153→    logger.info({
   154→        event: 'ai_request',
   155→        agent: metric.agent,
   156→        model: metric.model,
   157→        tokens: metric.totalTokens,
   158→        latencyMs: metric.latencyMs,
   159→        success: metric.success,
   160→        fallback: metric.fallbackUsed
   161→    });
   162→}
   163→
   164→/**
   165→ * Calculate estimated cost for tokens
   166→ */
   167→export function estimateCost(model: string, promptTokens: number, completionTokens: number): number {
   168→    const pricing = MODEL_PRICING[model] || MODEL_PRICING['gpt-4o'];
   169→    return (promptTokens * pricing.input + completionTokens * pricing.output) / 1_000_000;
   170→}
   171→
   172→/**
   173→ * Get aggregated metrics for a time period
   174→ */
   175→export function aggregateMetrics(
   176→    requests: RequestMetric[],
   177→    period: AggregatedMetrics['period']
   178→): AggregatedMetrics {
   179→    if (requests.length === 0) {
   180→        return {
   181→            period,
   182→            startTime: new Date().toISOString(),
   183→            endTime: new Date().toISOString(),
   184→            totalRequests: 0,
   185→            successfulRequests: 0,
   186→            failedRequests: 0,
   187→            totalTokens: 0,
   188→            totalPromptTokens: 0,
   189→            totalCompletionTokens: 0,
   190→            averageLatencyMs: 0,
   191→            p95LatencyMs: 0,
   192→            estimatedCostUsd: 0,
   193→            requestsByAgent: {},
   194→            requestsByModel: {},
   195→            toolUsage: {},
   196→            fallbackRate: 0,
   197→            errorRate: 0
   198→        };
   199→    }
   200→
   201→    const sorted = [...requests].sort((a, b) =>
   202→        new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()
   203→    );
   204→
   205→    const successful = requests.filter(r => r.success);
   206→    const failed = requests.filter(r => !r.success);
   207→    const withFallback = requests.filter(r => r.fallbackUsed);
   208→
   209→    const latencies = requests.map(r => r.latencyMs).sort((a, b) => a - b);
   210→    const p95Index = Math.floor(latencies.length * 0.95);
   211→
   212→    const requestsByAgent: Record<string, number> = {};
   213→    const requestsByModel: Record<string, number> = {};
   214→    const toolUsage: Record<string, number> = {};
   215→
   216→    let totalCost = 0;
   217→
   218→    for (const req of requests) {
   219→        requestsByAgent[req.agent] = (requestsByAgent[req.agent] || 0) + 1;
   220→        requestsByModel[req.model] = (requestsByModel[req.model] || 0) + 1;
   221→
   222→        for (const tool of req.toolsUsed) {
   223→            toolUsage[tool] = (toolUsage[tool] || 0) + 1;
