   292→/**
   293→ * Calculate total size of backup items
   294→ */
   295→export async function calculateBackupSize(items: BackupItem[]): Promise<number> {
   296→    logger.info({ itemCount: items.length }, 'Calculating backup size...');
   297→
   298→    let totalSize = 0;
   299→
   300→    for (const item of items) {
   301→        if (item.estimatedSize) {
   302→            totalSize += item.estimatedSize;
   303→        } else {
   304→            // Try to calculate size if not already estimated
   305→            try {
   306→                if (item.type === 'volume') {
   307→                    const size = await getVolumeSize(item.path);
   308→                    totalSize += size;
   309→                } else if (item.path.includes(':')) {
   310→                    // Container path format: "containerName:/path"
   311→                    const [containerName, containerPath] = item.path.split(':');
   312→                    const size = await getContainerPathSize(containerName, containerPath);
   313→                    totalSize += size;
   314→                }
   315→            } catch (error) {
   316→                logger.warn({ item: item.name }, 'Failed to calculate item size');
   317→            }
   318→        }
   319→    }
   320→
   321→    logger.info({ totalSize }, 'Size calculation complete');
   322→    return totalSize;
   323→}
